import { sql } from 'drizzle-orm';
import {
  boolean,
  index,
  integer,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uuid,
} from 'drizzle-orm/pg-core';

// An uploaded file. The bytes live in object storage under storageKey.
export const documents = pgTable('documents', {
  // Generated by the API, since the storage key is derived from it.
  id: uuid('id').primaryKey(),
  storageKey: text('storage_key').notNull(),
  filename: text('filename').notNull(),
  contentType: text('content_type').notNull(),
  sizeBytes: integer('size_bytes').notNull(),
  createdAt: timestamp('created_at', { withTimezone: true })
    .notNull()
    .defaultNow(),
});

export const runStatus = pgEnum('run_status', [
  'queued',
  'processing',
  'done',
  'failed',
]);

// One LLM pass over a document. Kept apart from documents so a stored file
// can be re-run with another prompt without losing earlier answers.
export const documentRuns = pgTable(
  'document_runs',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id),
    prompt: text('prompt').notNull(),
    status: runStatus('status').notNull().default('queued'),
    answer: text('answer'),
    error: text('error'),
    // Set along with error: false when trying again fails the same way
    // (missing or unreadable file), true when temporary errors used up every
    // attempt.
    retryable: boolean('retryable'),
    // Times the worker picked the run up, Kafka redeliveries included.
    attempts: integer('attempts').notNull().default(0),
    createdAt: timestamp('created_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true })
      .notNull()
      .defaultNow()
      // DB clock, like defaultNow(), so it's comparable with createdAt.
      .$onUpdate(() => sql`now()`),
  },
  (t) => [index('document_runs_document_id_idx').on(t.documentId)],
);

export type Document = typeof documents.$inferSelect;
export type NewDocument = typeof documents.$inferInsert;
export type DocumentRun = typeof documentRuns.$inferSelect;
